import re
from moler.exceptions import ParsingDone
from ta_moler.cmd.asimgr.genericasimgr import Genericasimgr


__author__ = 'Agnieszka Bylica'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'agnieszka.bylica@nokia.com'


class CollectSnapshot(Genericasimgr):
    """CollectSnapshot command class."""

    def __init__(self, ne, connection, prompt=None, newline_chars=None, runner=None, pw=None, outputdir='/home/ute/'):
        """
        Collectsnapshot command.

        :param ne: single IP address of one site.
        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        :param pw: sets of credentials for the sites.
        :param outputdir: path to saved snapshot file.
        """
        super(CollectSnapshot, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                              runner=runner)

        self.ne = ne
        self.pw = pw
        self.outputdir = outputdir

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"./ASiRManager.sh -ne {self.ne}"
        if self.pw:
            cmd = f"{cmd} -pw {self.pw}"
        cmd = f"{cmd} -savesnapshot -snapshotfilename {self.outputdir} -logcoverage all"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_success(line)
            except ParsingDone:
                pass
        return super(CollectSnapshot, self).on_new_line(line, is_full_line)

    # Snapshot saved successfully
    _re_finished_successfully = re.compile(r'Snapshot\s+saved\s+successfully', re.I)

    def _parse_line_success(self, line):
        if self._regex_helper.search_compiled(CollectSnapshot._re_finished_successfully, line):
            self.current_ret['RESULT'] = 'SUCCESS'
            raise ParsingDone


